const store = $getWorkflowStaticData('global');
store.records ??= [];
store.kv ??= {};
const op = String($json.operation || 'append').toLowerCase();
const requestId = String($json.request_id || '');
const key = String($json.key || requestId || 'default');
const limit = Math.max(1, Math.min(Number($json.limit || 50), 200));
const now = new Date().toISOString();

if (op === 'append') {
  const rec = { ts: now, request_id: requestId, key, value: $json.value ?? null };
  store.records.push(rec);
  if (store.records.length > 200) store.records = store.records.slice(-200);
  return [{json:{ok:true, operation:op, record:rec, size:store.records.length}}];
}
if (op === 'put') {
  store.kv[key] = { ts: now, value: $json.value ?? null };
  return [{json:{ok:true, operation:op, key, value:store.kv[key]}}];
}
if (op === 'get') return [{json:{ok:true, operation:op, key, value:store.kv[key] ?? null}}];
if (op === 'recent') return [{json:{ok:true, operation:op, records:store.records.slice(-limit)}}];
if (op === 'find_request') return [{json:{ok:true, operation:op, records:store.records.filter(r=>r.request_id===requestId).slice(-limit)}}];
return [{json:{ok:false,error:`Unsupported memory operation: ${op}`}}];
